<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin'})
const {data,refresh,error:fetchError}=await useFetch<any[]>('/api/admin/services')
const editing=ref<number|null>(null),adding=ref(false),saving=ref(false),error=ref(''),notice=ref('')
const blank=()=>({name:'',description:'',icon:'sparkles',duration_minutes:30,sort_order:0,is_active:true})
const form=reactive(blank())
const icons=['stethoscope','sparkles','shield-check','activity','sun','gem','smile','heart-handshake','calendar-check']
function reset(){Object.assign(form,blank());editing.value=null;adding.value=false;error.value=''}
function edit(s:any){Object.assign(form,{name:s.name,description:s.description,icon:s.icon,duration_minutes:s.duration_minutes,sort_order:s.sort_order,is_active:s.is_active});editing.value=Number(s.id);adding.value=true;error.value='';notice.value=''}
async function save(){error.value='';notice.value='';saving.value=true;try{const url=editing.value?`/api/admin/services/${editing.value}`:'/api/admin/services';await $fetch(url,{method:editing.value?'PATCH':'POST',body:{...form}});await refresh();reset();notice.value='تغییرات خدمات ذخیره شد.'}catch(e){error.value=humanError(e)}finally{saving.value=false}}
async function archive(s:any){if(!confirm(`خدمت «${s.name}» غیرفعال شود؟ سوابق نوبت‌های قبلی محفوظ می‌مانند.`))return;error.value='';try{await $fetch(`/api/admin/services/${s.id}`,{method:'DELETE'});await refresh();notice.value='خدمت غیرفعال شد.'}catch(e){error.value=humanError(e)}}
useSeoMeta({title:'مدیریت خدمات دندانپزشکی',robots:'noindex,nofollow'})
</script>
<template><div><div class="flex flex-wrap gap-4 items-center justify-between mb-8"><div><span class="eyebrow">لیست قابل ویرایش</span><h1 class="text-3xl font-extrabold text-jade-800 mt-2">خدمات دندانپزشکی</h1><p class="text-xs text-[#8ca195] mt-2">افزودن، ویرایش و غیرفعال کردن خدمات و مدت هر نوبت</p></div><button class="btn-main" @click="reset(),adding=true"><Icon name="plus" :size="18" /> افزودن خدمت جدید</button></div><p v-if="error" role="alert" class="p-4 bg-red-50 text-red-700 rounded-xl text-xs mb-4">{{error}}</p><p v-if="notice" class="p-4 bg-green-50 text-green-700 rounded-xl text-xs mb-4">{{notice}}</p><div v-if="adding" class="glass-card p-7 mb-6"><div class="flex justify-between items-center mb-6"><h2 class="font-bold text-jade-800">{{editing?'ویرایش خدمت':'خدمت جدید'}}</h2><button @click="reset"><Icon name="x" /></button></div><form class="grid sm:grid-cols-2 gap-5" @submit.prevent="save"><div><label class="field-label">نام خدمت *</label><input v-model="form.name" required class="input-field" maxlength="120" /></div><div><label class="field-label">مدت خدمت (دقیقه) *</label><input v-model.number="form.duration_minutes" type="number" min="15" max="240" class="input-field" required /></div><div class="sm:col-span-2"><label class="field-label">توضیحات</label><textarea v-model="form.description" maxlength="600" class="input-field" rows="3"></textarea></div><div><label class="field-label">آیکون</label><div class="flex flex-wrap gap-2"><button v-for="ic in icons" :key="ic" type="button" class="w-10 h-10 border rounded-xl grid place-items-center" :class="form.icon===ic?'bg-jade-700 text-white border-jade-700':'border-[#dce9df] text-jade-700'" :aria-label="ic" @click="form.icon=ic"><Icon :name="ic" :size="18" /></button></div></div><div><label class="field-label">ترتیب نمایش</label><input v-model.number="form.sort_order" type="number" min="0" max="1000" class="input-field" /><label class="flex items-center gap-2 mt-5 text-xs font-bold"><input v-model="form.is_active" type="checkbox" class="accent-[#0a5148]" /> فعال و قابل رزرو</label></div><div class="sm:col-span-2 flex gap-3"><button :disabled="saving" class="btn-main"><Icon name="check" :size="16" />{{saving?'در حال ذخیره...':'ذخیره خدمت'}}</button><button type="button" class="btn-light" @click="reset">انصراف</button></div></form></div><div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-5"><div v-for="s in data||[]" :key="s.id" class="glass-card p-6" :class="!s.is_active?'opacity-60':''"><div class="flex justify-between items-start mb-5"><span class="rounded-xl bg-jade-50 p-3 text-jade-700"><Icon :name="s.icon" :size="23" /></span><span class="status-pill" :class="s.is_active?'status-confirmed':'status-cancelled'">{{s.is_active?'فعال':'غیرفعال'}}</span></div><h3 class="font-bold text-jade-800">{{s.name}}</h3><p class="text-xs text-[#80978c] leading-8 mt-2 h-16 overflow-hidden">{{s.description}}</p><div class="pt-5 border-t border-[#ecf0ec] flex items-center justify-between mt-5"><span class="text-xs text-[#81978d] flex items-center gap-1"><Icon name="clock" :size="15" />{{faNumber(s.duration_minutes)}} دقیقه</span><div class="flex gap-2"><button class="w-9 h-9 rounded-lg bg-jade-50 text-jade-700 grid place-items-center" title="ویرایش" @click="edit(s)"><Icon name="pencil" :size="16" /></button><button v-if="s.is_active" class="w-9 h-9 rounded-lg bg-rose-50 text-rose-600 grid place-items-center" title="غیرفعال کردن" @click="archive(s)"><Icon name="trash-2" :size="16" /></button></div></div></div><p v-if="!data?.length" class="col-span-full text-sm text-[#8a9e94] p-10">{{fetchError?'ارتباط با سرور برقرار نیست.':'خدمتی تعریف نشده است.'}}</p></div></div></template>
